let onboardStep=0;
const onboardDraft={name:'',email:'',consent:false,connection:'student',interests:[],volunteer:false};
const onboardInterests=[['culture','Culture & Sudanese stories','الثقافة والقصص السودانية'],['social','Social gatherings','اللقاءات الاجتماعية'],['support','Student connections','التواصل بين الطلاب'],['service','Community service','خدمة المجتمع']];
const escapeOnboard=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function openOnboarding(){onboardStep=0;drawOnboarding();document.querySelector('#onboarding-dialog').showModal()}
function drawOnboarding(){const d=document.querySelector('#onboarding-dialog');
const stages=[tr('About you','عن نفسك'),tr('Your interests','اهتماماتك'),tr('Review','مراجعة')];
let body='';
if(onboardStep===0)body=`<h2 id="onboarding-title" tabindex="-1">${tr('Let’s start with hello.','نبدأ بالتعارف.')}</h2><p>${tr('Membership is free and open to everyone. Use a made-up name to try the experience.','العضوية مجانية ومفتوحة للجميع. يمكنك استخدام اسم تجريبي لتجربة الخطوات.')}</p><label for="onboard-name">${tr('First name or preferred name','الاسم الأول أو الاسم الذي تفضّله')}</label><input id="onboard-name" name="name" autocomplete="off" maxlength="60" required value="${escapeOnboard(onboardDraft.name)}" placeholder="${tr('e.g. Sam','مثلاً: سام')}"><label for="onboard-email">${tr('Email · use a sample address','البريد · استخدم عنواناً تجريبياً')}</label><input id="onboard-email" type="email" required maxlength="254" value="${escapeOnboard(onboardDraft.email)}" placeholder="you@example.com"><label class="onboard-option"><input id="onboard-consent" type="checkbox" required ${onboardDraft.consent?'checked':''}><span>${tr('I understand this is a membership demo; nothing is submitted.','أفهم أن هذه تجربة عضوية ولا تُرسل أي معلومات.')}</span></label><label for="onboard-connection">${tr('Your connection to campus','صلتك بالجامعة')}</label><select id="onboard-connection"><option value="student" ${onboardDraft.connection==='student'?'selected':''}>${tr('UAlberta student','طالب بجامعة ألبرتا')}</option><option value="alumni" ${onboardDraft.connection==='alumni'?'selected':''}>${tr('Alumni','خريج')}</option><option value="community" ${onboardDraft.connection==='community'?'selected':''}>${tr('Community member / other','عضو في المجتمع / غير ذلك')}</option></select><p class="onboard-small">${tr('Use fictional details. No student ID or phone number is requested.','استخدم معلومات تجريبية. لا يُطلب رقم طالب أو هاتف.')}</p>`;
if(onboardStep===1)body=`<h2 id="onboarding-title" tabindex="-1">${tr('What brings you here?','شنو اهتماماتك؟')}</h2><p>${tr('Pick anything you’re interested in, or skip this step.','اختر ما يهمك، أو تجاوز هذه الخطوة.')}</p><fieldset><legend>${tr('Interests (optional)','الاهتمامات (اختياري)')}</legend>${onboardInterests.map(([id,en,ar])=>`<label class="onboard-option"><input type="checkbox" name="interest" value="${id}" ${onboardDraft.interests.includes(id)?'checked':''}><span>${tr(en,ar)}</span></label>`).join('')}</fieldset><label class="onboard-option"><input id="onboard-volunteer" type="checkbox" ${onboardDraft.volunteer?'checked':''}><span>${tr('I’d like to hear about volunteering','أرغب في معرفة فرص التطوع')}</span></label>`;
if(onboardStep===2)body=`<h2 id="onboarding-title" tabindex="-1">${tr('Does this look like you?','هل هذه معلوماتك؟')}</h2><p>${tr('Here’s your demo introduction. Nothing will be sent when you finish.','هذا ملخص التعريف التجريبي بك. لن تُرسل أي معلومات عند الإكمال.')}</p><dl class="onboard-review"><dt>${tr('Name','الاسم')}</dt><dd>${escapeOnboard(onboardDraft.name)}</dd><dt>${tr('Email','البريد')}</dt><dd>${escapeOnboard(onboardDraft.email)}</dd><dt>${tr('Campus connection','الصلة بالجامعة')}</dt><dd>${onboardDraft.connection==='student'?tr('UAlberta student','طالب بجامعة ألبرتا'):onboardDraft.connection==='alumni'?tr('Alumni','خريج'):tr('Community member / other','عضو في المجتمع / غير ذلك')}</dd><dt>${tr('Interests','الاهتمامات')}</dt><dd>${onboardDraft.interests.map(id=>{const i=onboardInterests.find(x=>x[0]===id);return tr(i[1],i[2])}).join(' · ')||tr('Explore everything','استكشاف كل الأنشطة')}</dd><dt>${tr('Volunteering','التطوع')}</dt><dd>${onboardDraft.volunteer?tr('Interested','مهتم'):tr('Maybe later','ربما لاحقاً')}</dd></dl>`;
if(onboardStep===3)body=`<div class="onboard-welcome" aria-hidden="true">أهلاً بيك</div><h2 id="onboarding-title" tabindex="-1">${tr('You’ve reached the welcome step.','وصلت إلى خطوة الترحيب.')}</h2><p>${tr('Welcome,','مرحباً،')} <strong>${escapeOnboard(onboardDraft.name)}</strong>. ${tr('In a connected version, this is where you would receive your welcome email and community invitation.','في النسخة المتصلة، ستتلقى هنا رسالة ترحيب ودعوة للمجتمع.')}</p><p class="dialognote">${tr('Demo complete · You haven’t joined SSO, and no email or membership record was created.','اكتملت التجربة · لم يتم تسجيلك في المنظمة، ولم تُرسل رسالة أو يُنشأ سجل عضوية.')}</p><ol class="onboard-next"><li><b>${tr('Get connected','تواصل مع المجتمع')}</b><span>${tr('A future welcome message would include the club’s approved community link.','ستتضمن رسالة الترحيب مستقبلاً رابط المجتمع المعتمد.')}</span></li><li><b>${tr('Find your first gathering','اختر أول لقاء لك')}</b><span>${tr('Check the club’s current announcements for your next step.','راجع إعلانات المنظمة الحالية لمعرفة الخطوة التالية.')}</span></li><li><b>${onboardDraft.volunteer?tr('Offer a helping hand','شارك بجهدك'):tr('Bring a friend','تعال مع صديق')}</b><span>${onboardDraft.volunteer?tr('The team could follow up about volunteering after you opt in.','يمكن للفريق التواصل معك بشأن التطوع بعد موافقتك.'):tr('Share the community with someone who would enjoy it.','شارك المجتمع مع شخص قد يستمتع بالانضمام.')}</span></li></ol><a class="textlink" href="https://www.instagram.com/sso.uofa/" target="_blank" rel="noopener noreferrer">${tr('Visit the real SSO Instagram','زيارة حساب المنظمة الحقيقي')} </a>`;
d.innerHTML=`<button type="button" class="close" id="onboard-close" aria-label="${tr('Close onboarding','إغلاق خطوات الانضمام')}">×</button><span class="tag">${tr('MEMBER ONBOARDING · DEMO','خطوات الانضمام · تجربة')}</span><p class="onboard-small">${tr('Nothing is submitted. Your entries stay only in this tab until you reload or reset.','لا يتم إرسال أي معلومات. تبقى المدخلات في هذه الصفحة فقط حتى إعادة تحميلها أو إعادة ضبط التجربة.')}</p>${onboardStep<3?`<ol class="onboard-progress">${stages.map((s,i)=>`<li ${i===onboardStep?'aria-current="step"':''} class="${i<=onboardStep?'reached':''}"><span>${i+1}</span>${s}</li>`).join('')}</ol>`:''}<form id="onboard-form">${body}<div class="onboard-actions">${onboardStep>0&&onboardStep<3?`<button type="button" class="button light" id="onboard-back">${tr('Back','السابق')}</button>`:''}<button class="button" type="submit">${onboardStep===3?tr('Close demo','إغلاق التجربة'):onboardStep===2?tr('Finish demo','إكمال التجربة'):tr('Continue','متابعة')} </button>${onboardStep===3?`<button type="button" class="button light" id="onboard-reset">${tr('Try again','جرّب مجدداً')}</button>`:''}</div></form>`;
document.querySelector('#onboard-close').onclick=()=>d.close();
const save=()=>{if(onboardStep===0){onboardDraft.name=document.querySelector('#onboard-name').value.trim();onboardDraft.email=document.querySelector('#onboard-email').value;onboardDraft.consent=document.querySelector('#onboard-consent').checked;onboardDraft.connection=document.querySelector('#onboard-connection').value}else if(onboardStep===1){onboardDraft.interests=Array.from(d.querySelectorAll('[name=interest]:checked')).map(i=>i.value);onboardDraft.volunteer=document.querySelector('#onboard-volunteer').checked}};
d.querySelector('#onboard-form').oninput=save;d.querySelector('#onboard-form').onchange=save;
document.querySelector('#onboard-form').onsubmit=e=>{e.preventDefault();save();if(onboardStep===0&&!onboardDraft.name){document.querySelector('#onboard-name').setCustomValidity(tr('Please enter a name.','أدخل اسماً من فضلك.'));document.querySelector('#onboard-name').reportValidity();document.querySelector('#onboard-name').oninput=()=>document.querySelector('#onboard-name').setCustomValidity('');return}if(onboardStep===3){d.close();return}onboardStep++;drawOnboarding();d.scrollTop=0;document.querySelector('#onboarding-title').focus()};
if(document.querySelector('#onboard-back'))document.querySelector('#onboard-back').onclick=()=>{save();onboardStep--;drawOnboarding();document.querySelector('#onboarding-title').focus()};
if(document.querySelector('#onboard-reset'))document.querySelector('#onboard-reset').onclick=()=>{Object.assign(onboardDraft,{name:'',email:'',consent:false,connection:'student',interests:[],volunteer:false});onboardStep=0;drawOnboarding();document.querySelector('#onboarding-title').focus()};
}
function bindOnboarding(){document.querySelector('#try-onboarding').onclick=()=>window.open('https://campus.hellorubric.com/?s=14548','_blank','noopener,noreferrer');if(document.querySelector('#onboarding-dialog').open)drawOnboarding()}
